          ]
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "approved":   { "type": "boolean" },
            "risk_notes": { "type": "string" },
            "Action":     { "type": "string", "enum": ["Approve", "Reject"], "default": "Approve" }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "approvalDecision1",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Approved?"
      },
      "inputs": {
        "expression": "$vars.complianceReview1.output.approved === true",
        "trueLabel": "Approved",
        "falseLabel": "Rejected"
      }
    },
    {
      "id": "logOnboarded1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log Vendor Onboarded"
      },
      "inputs": {
        "script": "console.log(\"Vendor onboarded\");\nreturn { message: \"Vendor onboarded\" };"
      }
    },
    {
      "id": "logRejected1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log Vendor Rejected"
      },
      "inputs": {
        "script": "console.log(\"Vendor rejected\");\nreturn { message: \"Vendor rejected\" };"
      }
    },
    {
      "id": "endApproved1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End (Approved)"
      }
    },
    {
      "id": "endRejected1",
